from collections.abc import Iterable, Mapping

from stock_aggregate import aggregate_deltas


def reconcile_stock(
    opening: Mapping[str, int],
    adjustments: Iterable[Mapping[str, object]],
    counted: Mapping[str, int],
) -> list[dict[str, int | str]]:
    if not isinstance(opening, Mapping) or not isinstance(counted, Mapping):
        raise ValueError("invalid stock levels")
    for levels in (opening, counted):
        for sku, quantity in levels.items():
            if (type(sku) is not str or not sku or sku != sku.strip().upper()
                    or type(quantity) is not int or quantity < 0):
                raise ValueError("invalid stock levels")

    deltas = aggregate_deltas(adjustments)
    rows: list[dict[str, int | str]] = []
    for sku in sorted(set(opening) | set(counted) | set(deltas)):
        expected = opening.get(sku, 0) + deltas.get(sku, 0)
        actual = counted.get(sku, 0)
        difference = actual - expected
        if difference:
            rows.append({
                "sku": sku,
                "expected": expected,
                "counted": actual,
                "difference": difference,
            })
    return rows

