from collections.abc import Iterable, Mapping
from typing import cast

from stock_events import normalize_stock_delta


def aggregate_deltas(
    adjustments: Iterable[Mapping[str, object]],
) -> dict[str, int]:
    totals: dict[str, int] = {}
    for row in adjustments:
        normalized = normalize_stock_delta(row)
        sku = cast(str, normalized["sku"])
        delta = cast(int, normalized["delta"])
        totals[sku] = totals.get(sku, 0) + delta
    return {sku: totals[sku] for sku in sorted(totals)}
